<?php
declare(strict_types=1);
require dirname(__DIR__) . '/src/bootstrap.php';
if ($_SERVER['REQUEST_METHOD'] === 'POST') handlePost();
$user = currentUser();
$page = (string)($_GET['page'] ?? 'overview');
$pages = ['overview'=>'Overview','calendar'=>'Calendar','exams'=>'Exams','targets'=>'Targets','tasks'=>'Daily tasks','salary'=>'Salary','recovery'=>'Recovery','admin'=>'Admin center'];
if (!isset($pages[$page]) && !in_array($page, ['login','register'], true)) $page = 'overview';
$flash = $_SESSION['flash'] ?? null; unset($_SESSION['flash']);
$today = date('Y-m-d');
$release = json_decode((string)@file_get_contents(dirname(__DIR__, 2) . '/crab-release.json'), true) ?: [];
if ($user && (($page === 'admin' && $user['role'] !== 'admin') || ($page !== 'admin' && !allowed($user, $page)))) { http_response_code(403); $page = 'locked'; }

function fields(string $page, string $action): void { echo '<input type="hidden" name="csrf" value="' . h(csrf()) . '"><input type="hidden" name="return_page" value="' . h($page) . '"><input type="hidden" name="action" value="' . h($action) . '">'; }
function niceDate(string $date): string { return date('M j, Y', strtotime($date)); }
function addForm(string $page, string $kind, string $today): void {
    echo '<section class="glass form-panel"><h2>Add ' . h($kind) . '</h2><form method="post" class="entry-form">'; fields($page, 'add_item');
    echo '<input type="hidden" name="kind" value="' . h($kind) . '"><label>Title<input name="title" maxlength="150" placeholder="What needs to happen?" required></label><label>Due date<input type="date" name="due_at" value="' . h($today) . '" required></label><label class="wide-field">Notes<textarea name="details" maxlength="1000" rows="2" placeholder="Details, if useful"></textarea></label><label>Points<input type="number" name="points" value="10" min="0" max="1000" required></label><div class="submit-cell"><button class="button">Add ' . h($kind) . '</button></div></form></section>';
}
function itemCard(array $item, string $page): void {
    $state = $item['status'] === 'open' && $item['due_at'] < date('Y-m-d') ? 'missed' : $item['status'];
    echo '<article class="item glass"><div class="item-top"><span class="type-label">' . h(ucfirst($item['kind'])) . '</span><span class="badge ' . h($state) . '">' . h(ucfirst($state)) . '</span></div><h3>' . h($item['title']) . '</h3>';
    if ($item['details'] !== '') echo '<p class="item-detail">' . nl2br(h($item['details'])) . '</p>';
    echo '<div class="item-meta"><span>Due ' . h(niceDate($item['due_at'])) . '</span><span>+' . (int)$item['points'] . ' points</span></div>';
    if ($item['kind'] === 'target') echo '<div class="progress" role="progressbar" aria-label="Target progress" aria-valuenow="' . (int)$item['progress'] . '" aria-valuemin="0" aria-valuemax="100"><span style="width:' . (int)$item['progress'] . '%"></span></div><small>' . (int)$item['progress'] . '% complete</small>';
    echo '<div class="item-actions">';
    if ($state === 'missed' || $state === 'failed') {
        echo '<form method="post" class="inline-form">'; fields($page, 'update_item'); echo '<input type="hidden" name="id" value="' . (int)$item['id'] . '"><input type="hidden" name="operation" value="reschedule"><label class="sr-only" for="date-' . (int)$item['id'] . '">New date</label><input id="date-' . (int)$item['id'] . '" type="date" name="due_at" min="' . date('Y-m-d') . '" value="' . date('Y-m-d', strtotime('+1 day')) . '" required><button class="mini primary">Reschedule</button></form>';
    } elseif ($state === 'open') {
        echo '<form method="post">'; fields($page, 'update_item'); echo '<input type="hidden" name="id" value="' . (int)$item['id'] . '"><button class="mini primary" name="operation" value="done">Complete</button><button class="mini" name="operation" value="failed">Mark failed</button></form>';
    } else {
        echo '<form method="post">'; fields($page, 'update_item'); echo '<input type="hidden" name="id" value="' . (int)$item['id'] . '"><button class="mini" name="operation" value="reopen">Reopen</button></form>';
    }
    if ($item['kind'] === 'target' && $state === 'open') {
        echo '<form method="post" class="inline-form">'; fields($page, 'update_item'); echo '<input type="hidden" name="id" value="' . (int)$item['id'] . '"><label class="sr-only" for="progress-' . (int)$item['id'] . '">Progress percent</label><input class="small-number" id="progress-' . (int)$item['id'] . '" type="number" name="progress" min="0" max="100" value="' . (int)$item['progress'] . '"><button class="mini" name="operation" value="progress">Save %</button></form>';
    }
    echo '<details class="edit-details"><summary>Edit</summary><form method="post" class="edit-form">'; fields($page, 'update_item'); echo '<input type="hidden" name="id" value="' . (int)$item['id'] . '"><input type="hidden" name="operation" value="edit"><label>Title<input name="title" maxlength="150" value="' . h($item['title']) . '" required></label><label>Due date<input type="date" name="due_at" value="' . h($item['due_at']) . '" required></label><label>Notes<textarea name="details" maxlength="1000" rows="2">' . h($item['details']) . '</textarea></label><label>Points<input type="number" name="points" min="0" max="1000" value="' . (int)$item['points'] . '" required></label><button class="mini primary">Save changes</button></form></details>';
    echo '<form method="post" data-confirm="Delete this item?">'; fields($page, 'update_item'); echo '<input type="hidden" name="id" value="' . (int)$item['id'] . '"><button class="mini danger" name="operation" value="delete">Delete</button></form></div></article>';
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= h(($pages[$page] ?? ucfirst($page)) . ' · Crab') ?></title><link rel="stylesheet" href="/style.css"></head><body>
<?php if (!$user): ?>
<main class="auth-wrap"><section class="auth-card glass"><a class="auth-brand" href="/"><span class="logo">C</span> crab</a><div class="auth-heading"><span class="eyebrow">YOUR SPACE TO GROW</span><h1><?= $page === 'register' ? 'Create your account' : 'Welcome back' ?></h1><p>Keep your days, goals, and money in one clear place.</p></div>
<?php if ($flash): ?><div class="notice <?= h($flash['type']) ?>" role="alert"><?= h($flash['message']) ?></div><?php endif; ?>
<form method="post" class="auth-form"><?php fields($page, $page === 'register' ? 'register' : 'login'); ?><?php if ($page === 'register'): ?><label>Your name<input name="name" autocomplete="name" minlength="2" maxlength="80" required></label><?php endif; ?><label>Email address<input name="email" type="email" autocomplete="email" required></label><label>Password<input name="password" type="password" autocomplete="<?= $page === 'register' ? 'new-password' : 'current-password' ?>" minlength="8" required></label><button class="button wide" type="submit"><?= $page === 'register' ? 'Create account' : 'Sign in' ?></button></form><p class="auth-switch"><?= $page === 'register' ? 'Already have an account? <a href="/?page=login">Sign in</a>' : 'New to Crab? <a href="/?page=register">Create an account</a>' ?></p></section></main>
<?php else:
$userId = (int)$user['id'];
$items = array_values(array_filter(rows('SELECT * FROM items WHERE user_id = ? ORDER BY due_at ASC, id DESC', [$userId]), fn($i) => allowed($user, ['task'=>'tasks','exam'=>'exams','target'=>'targets','event'=>'calendar'][$i['kind']])));
$money = allowed($user, 'salary') ? rows('SELECT * FROM money WHERE user_id = ? ORDER BY entry_date DESC, id DESC', [$userId]) : [];
$recoveries = array_values(array_filter($items, fn($i) => $i['status'] === 'failed' || ($i['status'] === 'open' && $i['due_at'] < $today)));
$earned = array_sum(array_map(fn($i) => $i['status'] === 'done' ? (int)$i['points'] : 0, $items));
$income = array_sum(array_map(fn($m) => $m['kind'] === 'salary' && str_starts_with($m['entry_date'], date('Y-m')) ? (float)$m['amount'] : 0, $money));
$expense = array_sum(array_map(fn($m) => $m['kind'] === 'expense' && str_starts_with($m['entry_date'], date('Y-m')) ? (float)$m['amount'] : 0, $money));
?>
<div class="app-shell"><aside class="sidebar"><a class="brand" href="/"><span class="logo">C</span><span>crab</span></a><div class="nav-caption">WORKSPACE</div><nav aria-label="Main navigation"><?php foreach ($pages as $key => $name): if ($key === 'admin' ? $user['role'] !== 'admin' : !allowed($user, $key)) continue; ?><a class="nav-link <?= $page === $key ? 'active' : '' ?>" href="/?page=<?= h($key) ?>" <?= $page === $key ? 'aria-current="page"' : '' ?>><span class="nav-symbol" aria-hidden="true"><?= h(['overview'=>'◈','calendar'=>'▦','exams'=>'◇','targets'=>'◎','tasks'=>'☑','salary'=>'◌','recovery'=>'↺','admin'=>'⚙'][$key]) ?></span><span><?= h($name) ?></span><?php if ($key === 'recovery' && $recoveries): ?><span class="nav-count"><?= count($recoveries) ?></span><?php endif; ?></a><?php endforeach; ?></nav><div class="sidebar-bottom"><span>Crab <?= h($release['version'] ?? 'dev') ?></span><form method="post"><?php fields($page, 'logout'); ?><button class="signout">Sign out</button></form></div></aside>
<main class="main"><header class="topbar"><span><?= h(date('l, F j, Y')) ?></span><div class="user-chip"><span class="avatar"><?= h(mb_strtoupper(mb_substr($user['name'], 0, 1))) ?></span><span><?= h($user['name']) ?></span></div></header><div class="content"><?php if ($flash): ?><div class="notice <?= h($flash['type']) ?>" role="alert"><?= h($flash['message']) ?></div><?php endif; ?>
<?php if ($page === 'admin') require dirname(__DIR__) . '/src/admin.php'; ?>
<?php if ($page === 'locked'): ?><div class="page-heading"><span class="eyebrow">ACCESS</span><h1>Module locked</h1><p>Ask your administrator to unlock this part of Crab.</p></div>
<?php elseif ($page === 'overview'): ?>
<div class="page-heading"><span class="eyebrow">YOUR WORKSPACE</span><h1>Good <?= (int)date('G') < 12 ? 'morning' : ((int)date('G') < 17 ? 'afternoon' : 'evening') ?>, <?= h(explode(' ', trim($user['name']))[0]) ?>.</h1><p>See what matters today, then keep moving.</p></div><div class="stat-grid"><div class="stat glass"><span>Today’s tasks</span><strong><?= count(array_filter($items, fn($i) => $i['kind'] === 'task' && $i['due_at'] === $today && $i['status'] === 'open')) ?></strong><small>Still to do</small></div><div class="stat glass"><span>Needs attention</span><strong><?= count($recoveries) ?></strong><small>Missed or failed</small></div><div class="stat glass"><span>Points earned</span><strong><?= $earned ?></strong><small>Completed work</small></div><div class="stat glass"><span>Monthly balance</span><strong><?= number_format($income - $expense, 2) ?></strong><small>Salary minus expenses</small></div></div><div class="two-col"><section class="glass list-box"><div class="section-head"><h2>Coming up</h2><a href="/?page=calendar">Calendar →</a></div><?php $upcoming = array_slice(array_values(array_filter($items, fn($i) => $i['status'] === 'open' && $i['due_at'] >= $today)), 0, 5); if (!$upcoming): ?><p class="empty">Nothing upcoming. Add a task or event to get started.</p><?php else: foreach ($upcoming as $item): ?><div class="compact-row"><span class="compact-icon"><?= h(['task'=>'✓','exam'=>'◇','target'=>'◎','event'=>'▦'][$item['kind']]) ?></span><div><strong><?= h($item['title']) ?></strong><small><?= h(ucfirst($item['kind'])) ?> · <?= h(niceDate($item['due_at'])) ?></small></div></div><?php endforeach; endif; ?></section><section class="glass list-box"><div class="section-head"><h2>Pick up where you left off</h2><a href="/?page=recovery">Recovery →</a></div><?php if (!$recoveries): ?><p class="empty">You’re all caught up. Missed and failed work will appear here.</p><?php else: foreach (array_slice($recoveries, 0, 4) as $item): ?><div class="compact-row"><span class="compact-icon warning">↺</span><div><strong><?= h($item['title']) ?></strong><small><?= $item['status'] === 'failed' ? 'Failed' : 'Missed' ?> · <?= h(niceDate($item['due_at'])) ?></small></div></div><?php endforeach; endif; ?></section></div>
<?php elseif ($page === 'calendar'): ?>
<div class="page-heading"><span class="eyebrow">PLAN YOUR TIME</span><h1>Calendar</h1><p>One view for events, exams, targets, and tasks.</p></div><?php addForm('calendar','event',$today); $month = (string)($_GET['month'] ?? date('Y-m')); if (!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month)) $month=date('Y-m'); $first=new DateTimeImmutable($month.'-01'); $days=(int)$first->format('t'); $offset=(int)$first->format('N')-1; ?><section class="glass list-box calendar-section"><div class="section-head"><h2><?= h($first->format('F Y')) ?></h2><div class="month-nav"><a href="/?page=calendar&amp;month=<?= h($first->modify('-1 month')->format('Y-m')) ?>" aria-label="Previous month">←</a><a href="/?page=calendar&amp;month=<?= h($first->modify('+1 month')->format('Y-m')) ?>" aria-label="Next month">→</a></div></div><div class="calendar-grid"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day): ?><div class="day-name"><?= $day ?></div><?php endforeach; for($blank=0;$blank<$offset;$blank++): ?><div class="day-cell outside"></div><?php endfor; for($day=1;$day<=$days;$day++): $date=sprintf('%s-%02d',$month,$day); $dayItems=array_values(array_filter($items,fn($i)=>$i['due_at']===$date)); ?><div class="day-cell <?= $date===$today?'today':'' ?>"><strong><?= $day ?></strong><?php foreach(array_slice($dayItems,0,3) as $item): ?><span class="calendar-item <?= h($item['kind']) ?>" title="<?= h($item['title']) ?>"><?= h($item['title']) ?></span><?php endforeach; if(count($dayItems)>3): ?><small>+<?= count($dayItems)-3 ?> more</small><?php endif; ?></div><?php endfor; ?></div></section>
<?php require dirname(__DIR__) . '/src/events.php'; ?>
<?php elseif (in_array($page,['tasks','exams','targets'],true)): $kind=['tasks'=>'task','exams'=>'exam','targets'=>'target'][$page]; ?><div class="page-heading"><span class="eyebrow">STAY ON TRACK</span><h1><?= h($pages[$page]) ?></h1><p><?= h(['tasks'=>'Keep daily work clear and manageable.','exams'=>'Track dates and preparation.','targets'=>'Turn goals into visible progress.'][$page]) ?></p></div><?php addForm($page,$kind,$today); $filtered=array_values(array_filter($items,fn($i)=>$i['kind']===$kind)); ?><section class="list-section"><div class="section-head"><h2>Your <?= h($page) ?></h2><span class="muted"><?= count($filtered) ?> total</span></div><div class="item-grid"><?php if(!$filtered): ?><p class="empty">Nothing here yet. Add your first <?= h($kind) ?> above.</p><?php else: foreach($filtered as $item) itemCard($item,$page); endif; ?></div></section>
<?php elseif ($page==='recovery'): ?><div class="page-heading"><span class="eyebrow">START AGAIN</span><h1>Recovery</h1><p>Give missed or failed work a new date.</p></div><section class="list-section"><div class="section-head"><h2>Needs a new plan</h2><span class="muted"><?= count($recoveries) ?> items</span></div><div class="item-grid"><?php if(!$recoveries): ?><p class="empty">Nothing needs recovery right now.</p><?php else: foreach($recoveries as $item) itemCard($item,'recovery'); endif; ?></div></section>
<?php elseif ($page==='salary'): require dirname(__DIR__) . '/src/salary.php'; ?><?php endif; ?></div></main></div>
<?php endif; ?><script src="/visuals.js" defer></script></body></html>
